  const a = r.authority === undefined ? {} : splitAuthority(r.authority)
  checkPct(r.path, 'path')
  checkPct(a.userinfo, 'userinfo')
  checkPct(a.host, 'host')
  checkPct(r.query, 'query')
  checkPct(r.fragment, 'fragment')
