    t = { scheme: base.scheme, authority: base.authority, path: ref.path, query: ref.query, fragment: ref.fragment }
  } else {
    let path
    if (base.authority !== undefined && base.path === '') path = '/' + ref.path
    else path = base.path.slice(0, base.path.lastIndexOf('/') + 1) + ref.path
    t = { scheme: base.scheme, authority: base.authority, path, query: ref.query, fragment: ref.fragment }
  }
  checkAll(t)
  return normalizeParsed(t)
}
